mapper.select:
select r.id, r.season_id as seasonId, r.stage_id as stageId, r.rank_type as rankType, r.player_id as playerId, p.player_no as playerNo, ifnull(nullif(p.game_nickname, ''), mp.nickname) as displayName, af.access_url as avatarUrl, r.team_id as teamId, t.team_name as teamName, r.rank_no as rankNo, r.previous_rank as previousRank, case when r.previous_rank is null then null else (r.previous_rank - r.rank_no) end as rankChange, r.stat_value as statValue, s.games as games, r.snapshot_date as snapshotDate from basket_player_rank r left join basket_player_profile p on p.id = r.player_id and p.is_delete = 0 left join basket_member_profile mp on mp.member_id = p.member_id and mp.is_delete = 0 left join basket_file_asset af on af.id = mp.avatar_file_id and af.is_delete = 0 left join basket_team t on t.id = r.team_id and t.is_delete = 0 left join basket_player_season_stat s on s.season_id = r.season_id and s.stage_id = r.stage_id and s.player_id = r.player_id and s.is_delete = 0 where r.is_delete = 0 and r.snapshot_date = ( select max(r2.snapshot_date) from basket_player_rank r2 where r2.is_delete = 0 and r2.season_id = r.season_id and r2.stage_id = r.stage_id and r2.rank_type = r.rank_type ) and r.season_id = #{seasonId} and r.stage_id = #{stageId} and r.rank_type = #{rankType} and r.team_id = #{teamId}
and (p.game_nickname like concat('%', #{keyword}, '%') or mp.nickname like concat('%', #{keyword}, '%') or p.player_no like concat('%', #{keyword}, '%'))
order by r.rank_no, r.player_id

mapper.delete:
delete from basket_player_rank
where season_id = #{seasonId}
  and stage_id = #{stageId} and snapshot_date = #{snapshotDate}

mapper.select:
select rank_no from basket_player_rank
where is_delete = 0 and season_id = #{seasonId} and stage_id = #{stageId}
  and rank_type = #{rankType} and player_id = #{playerId}
  and snapshot_date < #{beforeDate}
order by snapshot_date desc
limit 1
